import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

export default function EmailVerificationPage() {
  const navigate = useNavigate();
  const [seconds, setSeconds] = useState(1421);

  useEffect(() => {
    if (seconds <= 0) return;
    const t = setInterval(() => setSeconds((s) => s - 1), 1000);
    return () => clearInterval(t);
  }, [seconds]);

  const fmt = (s) =>
    `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  const steps = [
    { n: 1, text: <span>Open the email from <strong>noreply@workbridge.dz</strong></span> },
    { n: 2, text: <span>Click <strong>"Verify my email"</strong> — you'll be brought back here automatically</span> },
    { n: 3, text: "Your account will be activated and you can complete your profile" },
  ];

  return (
    <div className="min-h-screen bg-cream flex flex-col">
      {/* Topbar - شفاف مع لوغو أحمر */}
      <div className="h-14 bg-transparent flex items-center justify-between px-8">
        <div className="flex items-center gap-2 cursor-pointer" onClick={() => navigate("/")}>
          {/* تم تغيير الخلفية إلى bg-red لتتناسب مع طلبك */}
          <div className="w-8 h-8 bg-red rounded-lg flex items-center justify-center text-white font-bold text-sm">A</div>
          <span className="font-semibold text-navy">WorkBridge DZ</span>
        </div>
        <button onClick={() => navigate("/sign-in")} className="text-sm text-gray-500 hover:text-navy transition-colors">
          ← Sign out
        </button>
      </div>

      {/* Body */}
      <div className="flex-1 flex flex-col items-center justify-center px-6 py-14 text-center">

        {/* Envelope with circles */}
        <div className="relative w-32 h-32 flex items-center justify-center mb-5">
          <div className="absolute w-32 h-32 rounded-full border border-gray-300" />
          <div className="absolute w-24 h-24 rounded-full border border-gray-200" />
          <div className="relative z-10">
            <svg width="40" height="32" viewBox="0 0 40 32" fill="none">
              <rect x="1" y="1" width="38" height="28" rx="4" fill="#dbeafe" stroke="#93c5fd" strokeWidth="1.5"/>
              <path d="M1 5 L20 18 L39 5" stroke="#93c5fd" strokeWidth="1.5" strokeLinecap="round"/>
              <circle cx="32" cy="6" r="6" fill="#f59e0b"/>
              <text x="32" y="9.5" textAnchor="middle" fontSize="8" fill="white" fontWeight="bold">!</text>
            </svg>
          </div>
        </div>

        {/* Awaiting badge */}
        <span className="inline-flex items-center gap-2 text-xs font-medium text-yellow-700 bg-yellow-100 border border-yellow-300 px-4 py-1.5 rounded-full mb-5">
          ⏱ Awaiting verification
        </span>

        <h1 className="font-serif text-4xl font-normal mb-3 text-navy">Verify your email address</h1>
        <p className="text-sm text-gray-500 mb-1">We've sent a verification link to</p>
        <p className="font-semibold text-gray-900 mb-10">ya***ne@gmail.com</p>

        {/* Card */}
        <div className="bg-white rounded-2xl border border-gray-200 p-8 w-full max-w-md mb-6 shadow-sm text-left">
          <p className="text-[11px] tracking-widest text-gray-400 uppercase mb-6">
            How to verify
          </p>

          <div className="flex flex-col gap-5 mb-7">
            {steps.map((s) => (
              <div key={s.n} className="flex items-start gap-4">
                <div className="w-7 h-7 rounded-full bg-cream border border-gray-200 flex items-center justify-center text-xs font-medium flex-shrink-0">
                  {s.n}
                </div>
                <p className="text-sm text-gray-800 leading-relaxed pt-1">{s.text}</p>
              </div>
            ))}
          </div>

          <div className="flex items-center justify-between pt-5 border-t border-gray-100">
            <span className="text-sm text-gray-500">
              ⏱ Link expires in <strong className="text-gray-900">{fmt(seconds)}</strong>
            </span>

            <button
              onClick={() => navigate("/onboarding/company")} 
              className="text-sm text-navy font-medium hover:underline flex items-center gap-1"
            >
              Resend email →
            </button>
          </div>
        </div>

        {/* Wrong email */}
        <p className="flex items-center gap-2 text-sm text-gray-500">
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
            <polyline points="22,6 12,13 2,6"/>
          </svg>
          Wrong email address?{" "}
          <span className="text-navy font-medium cursor-pointer hover:underline" onClick={() => navigate("/register")}>
            Change email →
          </span>
        </p>
      </div>
    </div>
  );
}
